import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CXX_0q1Z.js";var i=JSON.parse(`{"title":"Events","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/skills/events.md","filePath":"en/modules/skills/events.md","lastUpdated":0}`),a={name:`en/modules/skills/events.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="events" tabindex="-1">Events <a class="header-anchor" href="#events" aria-label="Permalink to “Events”">​</a></h1><p>All player events fire synchronously on that player&#39;s owner thread. Asynchronous cast entry points hop back to the owner thread before publishing. Pre events are cancellable; post events are informational and fire after their corresponding commit.</p><table tabindex="0"><thead><tr><th>Event</th><th>Timing</th><th>Cancellable</th><th>Mutable field</th><th>Cancellation/effect</th><th>Runtime path</th></tr></thead><tbody><tr><td><code>SkillPreCastEvent</code></td><td>After condition, cooldown, and resource checks, before the skill effect</td><td>Yes</td><td>None</td><td>Stops the effect, resource consumption, and cooldown commit</td><td><code>CastAttemptService</code> active/passive, <code>cast</code>, and <code>castByTrigger</code> paths</td></tr><tr><td><code>SkillPostCastEvent</code></td><td>After the effect succeeds and resources and cooldowns have been committed for the current session</td><td>No</td><td>None</td><td>Post notification; cannot be rolled back</td><td>Successful <code>CastAttemptService.finalizeAttempt</code>; not fired on failure or source loss</td></tr><tr><td><code>SkillPreUpgradeEvent</code></td><td>After upgrade validation, before charging and the roll</td><td>Yes</td><td><code>successRate</code></td><td>Stops charging and the upgrade</td><td><code>SkillUpgradeService</code></td></tr><tr><td><code>SkillUpgradeEvent</code></td><td>After the upgrade attempt result (success or failure) has been applied</td><td>No</td><td>None</td><td>Post notification</td><td><code>SkillUpgradeService</code></td></tr><tr><td><code>PlayerSkillSlotChangeEvent</code></td><td>Before an equip, unequip, or bind-trigger write</td><td>Yes</td><td>None</td><td>Prevents the slot change</td><td>The three state paths in <code>PlayerSkillStateService</code></td></tr></tbody></table><h2 id="event-fields" tabindex="-1">Event fields <a class="header-anchor" href="#event-fields" aria-label="Permalink to “Event fields”">​</a></h2><table tabindex="0"><thead><tr><th>Event</th><th>Read-only fields</th><th>Writable fields</th></tr></thead><tbody><tr><td><code>SkillPreCastEvent</code></td><td><code>player</code>, <code>skillId</code>, <code>triggerId</code></td><td><code>cancelled</code></td></tr><tr><td><code>SkillPostCastEvent</code></td><td><code>player</code>, <code>skillId</code>, <code>triggerId</code></td><td>none beyond the handler list</td></tr><tr><td><code>SkillPreUpgradeEvent</code></td><td><code>player</code>, <code>skillId</code>, <code>currentLevel</code>, <code>targetLevel</code>, <code>maxLevel</code></td><td><code>cancelled</code>, <code>successRate</code></td></tr><tr><td><code>SkillUpgradeEvent</code></td><td><code>player</code>, <code>skillId</code>, <code>fromLevel</code>, <code>toLevel</code>, <code>successRate</code>, <code>success</code>, <code>downgraded</code></td><td>none</td></tr><tr><td><code>PlayerSkillSlotChangeEvent</code></td><td><code>player</code>, <code>slotIndex</code>, <code>skillId</code>, <code>triggerId</code>, <code>action</code></td><td><code>cancelled</code></td></tr></tbody></table><p><code>PlayerSkillSlotChangeEvent.Action</code> values: <code>EQUIP</code> (a skill is equipped), <code>UNEQUIP</code> (the slot is cleared), <code>BIND_TRIGGER</code> (a trigger is bound). On <code>UNEQUIP</code>, <code>skillId</code> is the previously bound skill id, and <code>triggerId</code> is non-null only for <code>BIND_TRIGGER</code>.</p><h2 id="boundaries" tabindex="-1">Boundaries <a class="header-anchor" href="#boundaries" aria-label="Permalink to “Boundaries”">​</a></h2><ul><li><code>SkillPostCastEvent</code> carries only player, skillId, and triggerId, and is never cancellable.</li><li><code>SkillPreUpgradeEvent</code> is published before charging, so cancelling it produces no costs to refund.</li><li><code>SkillUpgradeEvent</code> is published after the level (or the failure penalty) has been applied; listeners can observe but cannot change the result.</li><li>Script actions and external skill-source providers are extension execution points: registering one does not by itself fire events. Only operations that actually enter the central cast/upgrade/slot services cover these events.</li><li>Events are called synchronously by the plugin; listeners must not block inside them or touch Bukkit state owned by another entity.</li></ul>`,8)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};